    def select_dataset_eval_path(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')

        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.Directory)

        self.file_dialog_dataset_eval = file_dialog.exec()
        
        if self.file_dialog_dataset_eval == QtWidgets.QFileDialog.DialogCode.Accepted:

            self.path_dataset_eval = file_dialog.selectedFiles()[0]

            self.register_dataset_eval()

            self.write_dataset_path()

    def register_dataset_eval(self):

        try: 

            self.count +=1 

            self.dataset_eval_name = "my_dataset_eval_" + str(self.count)

            # dataset name, json path, images path
            register_coco_instances(self.dataset_eval_name, {}, self.path_dataset_eval  + "/instances_val.json", self.path_dataset_eval) 

            self.nuts_metadata = MetadataCatalog.get(self.dataset_eval_name)
            
            self.dataset_dicts = DatasetCatalog.get(self.dataset_eval_name)

            self.labelOutPut.appendPlainText("Dataset Registered. \n")

            self.dataset_registered = True

        except Exception as e: 

            self.labelOutPut.appendPlainText("Error when registering a new dataset. Please note the annotations json has to be named \"instances_val.json\"")

            self.labelOutPut.appendPlainText(str(e))

    def check_selection(self):
        
        if (self.model_path_loaded == None) or (self.file_dialog_dataset_eval == None) or (self.dataset_registered == False):

            missing_fields = []
            
            if self.model_path_loaded == None:

                missing_fields.append("Please Select Model")

            if self.file_dialog_dataset_eval == None:

                missing_fields.append("Please Select Dataset to Eval")

            if self.dataset_registered == False:

                missing_fields.append("No dataset registered")

            error_message = "\n".join(missing_fields)
            
            QtWidgets.QMessageBox.warning(self, "Selection Error", error_message)
        
        else:

            self.plot_prediction()

            self.COCO_eval_thread()

            #self.labelOutPut.appendPlainText("Done.")

    def load_model(self):

        try:

            self.cfg = get_cfg()
            self.cfg.merge_from_file(os.path.join(basedir, "detectron2Files", "mask_rcnn_X_101_32x8d_FPN_3x.yaml"))
            self.cfg.DATALOADER.NUM_WORKERS = 2
            self.cfg.MODEL.DEVICE = 'cpu'
            self.cfg.MODEL.WEIGHTS = self.model_path
            self.cfg.SOLVER.IMS_PER_BATCH = 1  # This is the real "batch size" commonly known to deep learning people
            self.cfg.MODEL.ROI_HEADS.BATCH_SIZE_PER_IMAGE = 1024   # The "RoIHead batch size".
            self.cfg.MODEL.ROI_HEADS.NUM_CLASSES = self.spinBoxNumOfClasses.value() 
            self.cfg.MODEL.ROI_HEADS.SCORE_THRESH_TEST = self.doubleSpinBoxIoUThresh.value()   # set a custom testing threshold
            self.predictor = DefaultPredictor(self.cfg)

            self.labelOutPut.appendPlainText("Model Loaded.")
            
        except Exception as e:

                self.labelOutPut.appendPlainText("Error when loading the model.")

                self.labelOutPut.appendPlainText(str(e))


    def import_model(self):
        
        file_dialog = QtWidgets.QFileDialog(directory='./')
        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.ExistingFile)
        file_dialog.setNameFilter("Arquivos pth (*.pth);;Todos os arquivos (*)")

        self.model_path_loaded = file_dialog.exec()

        if self.model_path_loaded == QtWidgets.QFileDialog.DialogCode.Accepted:
            
            self.model_path  = file_dialog.selectedFiles()[0]

            self.load_model()

            self.write_model_name()

    def update_model(self):

        if self.model_path_loaded != None:

            self.load_model()

    def create_canvas(self, figure, label):
        
        # Create a canvas to render the figure
        self.canvas = FigureCanvasQTAgg(figure)
        # Remove previous items from the scene
        label.clear()
        self.canvas.draw()

        size = self.canvas.size()
        width, height = size.width(), size.height()
        img = QtGui.QImage(self.canvas.buffer_rgba(), width, height, QtGui.QImage.Format.Format_RGBA8888)
        pixmap = QtGui.QPixmap(img)

        label.setPixmap(pixmap.scaled(512, 512, QtCore.Qt.AspectRatioMode.KeepAspectRatio, 
                                           QtCore.Qt.TransformationMode.SmoothTransformation))
        label.setScaledContents(True)
        label.setAlignment(QtCore.Qt.AlignmentFlag.AlignTop | QtCore.Qt.AlignmentFlag.AlignLeft)

    
    def plot_prediction(self):
    
        for d in random.sample(self.dataset_dicts, 1):

            img = cv2.imread(d["file_name"])

            _, tail = os.path.split(d["file_name"])

            outputs = self.predictor(img)  # format is documented at https://detectron2.readthedocs.io/tutorials/models.html#model-output-format
            v = Visualizer(img[:, :, ::-1],
                        metadata=self.nuts_metadata,
                        scale=1,
                        instance_mode=ColorMode.IMAGE_BW   # remove the colors of unsegmented pixels. This option is only available for segmentation models
            )
            out = v.draw_instance_predictions(outputs["instances"].to("cpu"))
           
            final_image = out.get_image()[:, :, ::-1]

            figure = Figure(facecolor='#F0F0F0', dpi=500)
      
            axes = figure.gca()

            axes.set_title("Predictions for file \n" + tail, fontdict= {'fontsize': 8})

            axes.axis("off")

            axes.imshow(final_image, cmap='gray')
            
            self.create_canvas(figure, self.labelVisualisePred)

    def write_model_name(self):
        try:
            # Change the button text
            self.pushButtonSelectModel.setText("Model Loaded: " + self.model_path)
        
        except: pass 

    def write_dataset_path(self):
        try:
            # Change the button text
            self.pushButtonSelectDataset.setText("File Loaded: " + self.path_dataset_eval)
        
        except: pass

    def COCO_eval_thread(self):

        self.import_thread = COCOEvalThread(self.dataset_eval_name, self.cfg, self.predictor, self.labelOutPut)

        self.text_edit_handler.log_signal.connect(self.update_log_label)

        # Start thread
        self.import_thread.start()

    def update_log_label(self, msg):

        self.labelOutPut.appendPlainText(msg)

